import { mount, signal, delegate } from 'kerfjs';
import { delegateActions } from 'kerfjs/actions';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { ValueTable } from '@kerfjs/ui/value-table';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import '@awesome.me/webawesome/dist/components/button/button.js';
import './details.css';
type Item = { id: string; title: string; owner: string; status: string };
type DialogElement = HTMLElement & { open: boolean };
export function mountDetails(root: HTMLElement, items: readonly Item[], app: { openItem(id: string): void; archive(id: string): void }) {
 const selected = signal(items[0]?.id ?? '');
 const opened = { value: false };
 let trigger: HTMLElement | undefined;
 const stopMount = mount(root, () => {
  const item = items.find(item => item.id === selected.value);
  return <section class="details-root kui-layout">
   <button type="button" data-action="show">View item details</button>
   <wa-dialog class="details-dialog" label="Item details" aria-labelledby="details-title" aria-describedby="details-summary" without-header open={opened.value}>
    <DialogHeader title="Item details" titleId="details-title" summary="Select an item to review its metadata and available actions." summaryId="details-summary" actions={<wa-button data-action="close" appearance="plain">Close</wa-button>} />
    <div class="details-columns">
     <nav class="kui-sidebar" aria-label="Items"><MenuHeader label="Available items" />{items.map(row => <MenuItem label={row.title} action="select-item" itemId={row.id} selected={row.id === selected.value} multiline />)}</nav>
     <section class="kui-dialog-body kui-section-stack" aria-live="polite">{item ? <><h3>{item.title}</h3><ValueTable label="Item metadata"><div><dt>Owner</dt><dd>{item.owner}</dd></div><div><dt>Status</dt><dd>{item.status}</dd></div></ValueTable><div class="kui-control-cluster"><wa-button data-action="archive" appearance="outlined">Archive item</wa-button><wa-button data-action="open-item" variant="brand" appearance="accent">Open item</wa-button></div></> : <p>No items are available.</p>}</section>
    </div>
   </wa-dialog>
  </section>;
 });
 const dialog = () => root.querySelector<DialogElement>('wa-dialog')!;
 const stopActions = delegateActions(root, 'click', {
  show: (_e, element) => { trigger = element as HTMLElement; trigger.focus(); opened.value = true; dialog().open = true; },
  close: () => { dialog().open = false; },
  'select-item': (_e, element) => { selected.value = (element as HTMLElement).dataset.itemId!; },
  archive: () => { if (selected.value) app.archive(selected.value); },
  'open-item': () => { if (selected.value) app.openItem(selected.value); }
 });
 const stopHide = delegate(root, 'wa-after-hide', 'wa-dialog', () => { opened.value = false; if (trigger?.isConnected) trigger.focus(); });
 return () => { stopHide(); stopActions(); stopMount(); };
}

