.details-root { min-width: 0; color: var(--kui-color-text); }
.details-dialog { --spacing: 0; --width: min(60rem, calc(100vw - 2rem)); }
/* The dialog body owns overflow; neither column adds a scroll container. */
.details-columns { display: grid; grid-template-columns: minmax(12rem,.8fr) minmax(0,1.4fr); }
.details-columns > nav { border-inline-end: 1px solid var(--kui-color-border); }
.details-columns > section { min-width: 0; overflow-wrap: anywhere; }
.details-columns h3 { margin: 0; }
@media(max-width:44rem) { .details-columns { grid-template-columns: minmax(0,1fr); } .details-columns > nav { border-inline-end: 0; border-block-end: 1px solid var(--kui-color-border); } }
.details-root button:focus-visible { outline: var(--kui-focus-ring); }
